-- Description: Current active relationship for LNK_KIMBLEONEACTIVITYASSIGNMENTC_CANDIDATE using ROW_NUMBER()
-- Generated by: bv pipeline generate transform
-- Link Type: RELATIONSHIP_BASED_LINK

WITH RANKED_RELATIONSHIPS AS (
SELECT
    l.LNK_KIMBLEONEACTIVITYASSIGNMENTC_CANDIDATE_HKEY AS LNK_KIMBLEONEACTIVITYASSIGNMENTC_CANDIDATE_HKEY,
    l.KIMBLEONE__ACTIVITYASSIGNMENT__C_HKEY AS KIMBLEONE__ACTIVITYASSIGNMENT__C_HKEY,
    l.CANDIDATE_HKEY AS CANDIDATE_HKEY,

    -- TODO: use generated tag instead of well-known name _CURRENT_ACTIVE_TIMESTAMP
    ls._CURRENT_ACTIVE_TIMESTAMP AS _CURRENT_RELATIONSHIP_TIMESTAMP, -- was ls._AIRBYTE_EXTRACTED_AT

    ROW_NUMBER() OVER (
        PARTITION BY l.KIMBLEONE__ACTIVITYASSIGNMENT__C_HKEY -- parent hub hk
        ORDER BY ls._CURRENT_ACTIVE_TIMESTAMP DESC -- TODO: as above. Was ls._AIRBYTE_EXTRACTED_AT
    ) AS row_num

FROM {{ source('eli_dv_rv', 'lnk_kimbleoneactivityassignmentc_candidate') }} l
INNER JOIN {{ ref('lks_sk_kimbleoneactivityassignmentc_candidate_curr') }} ls
    ON l.LNK_KIMBLEONEACTIVITYASSIGNMENTC_CANDIDATE_HKEY = ls.LNK_KIMBLEONEACTIVITYASSIGNMENTC_CANDIDATE_HKEY
)

SELECT * EXCLUDE (row_num)
FROM RANKED_RELATIONSHIPS
WHERE row_num = 1
